192	      result = await runOnce(command, timeoutMs);
193	    } catch {
194	      reportStartupFailure('measure', index, null);
195	      return { samples, errors, fatal: true };
196	    }
197	    if (result.reason === 'timeout') {
198	      errors.push({ stage: 'measure', index, reason: 'timeout', exit_code: null });
199	      continue;
200	    }
201	    if (isStartupExitCode(result.exitCode)) {
202	      reportStartupFailure('measure', index, result.exitCode);
203	      return { samples, errors, fatal: true };
