170	  const s1 = v1 / n1;
171	  const s2 = v2 / n2;
172	  const t = (m2 - m1) / Math.sqrt(s1 + s2);
173	  const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
174	  const p = regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
