'use strict';

const fs = require('node:fs/promises');
const {
  parseArgs,
  parsePositiveIntOption,
  runOnce,
  emptySummary,
  computeSummary,
  isStartupExitCode,
  EXIT_OK,
  EXIT_USAGE,
  EXIT_MEASURE_ERROR,
  EXIT_OUTPUT_ERROR,
} = require('./collect');
const {
  buildCompareResult,
  decide,
  parseNumberOption,
  DEFAULT_ALPHA,
  DEFAULT_MIN_CHANGE_PERCENT,
} = require('./compare');

const KNOWN_KEYS = new Set([
  'baseline-command',
  'candidate-command',
  'runs',
  'warmup',
  'timeout-ms',
  'output',
  'alpha',
  'min-change-percent',
]);

function fail(message) {
  process.stderr.write(`perf-regress: ${message}\n`);
  return EXIT_USAGE;
}

// 启动失败：按 nonzero_exit 记录到 stderr（含所属侧）；
// 按约定整体退出码 2，且不创建或改写 output。
function reportStartupFailure(side, stage, index, exitCode) {
  const record = { side, stage, index, reason: 'nonzero_exit', exit_code: exitCode };
  process.stderr.write(`perf-regress: 进程无法启动 ${JSON.stringify(record)}\n`);
}

// 交错执行两侧命令：先按轮次完成全部预热，再按轮次交错测量，
// 每轮先 baseline 后 candidate，全程串行。
// warmup 的 nonzero_exit/timeout 只记录；measure 的同类错误跳过该次后继续；
// 单侧异常不影响另一侧及后续轮次。
// 返回 { baseline, candidate, fatal }：两侧各含 { samples, errors }，
// errors 的 index 在本侧从 0 计数；fatal=true 表示进程无法启动
// （spawn 抛错或 shell 126/127），已向 stderr 报告，调用方须以退出码 2
// 终止且不得写 output。
async function executeInterleaved(baselineCommand, candidateCommand, runs, warmup, timeoutMs) {
  const sides = {
    baseline: { command: baselineCommand, samples: [], errors: [] },
    candidate: { command: candidateCommand, samples: [], errors: [] },
  };
  const order = ['baseline', 'candidate'];

  const runSide = async (sideName, stage, index) => {
    const side = sides[sideName];
    let result;
    try {
      result = await runOnce(side.command, timeoutMs);
    } catch {
      reportStartupFailure(sideName, stage, index, null);
      return false;
    }
    if (result.reason === 'timeout') {
      side.errors.push({ stage, index, reason: 'timeout', exit_code: null });
      return true;
    }
    if (isStartupExitCode(result.exitCode)) {
      reportStartupFailure(sideName, stage, index, result.exitCode);
      return false;
    }
    if (result.exitCode !== 0) {
      side.errors.push({ stage, index, reason: 'nonzero_exit', exit_code: result.exitCode });
      return true;
    }
    if (stage === 'measure') {
      side.samples.push({
        index,
        started_at: result.startedAt.toISOString(),
        duration_ns: result.durationNs,
        exit_code: result.exitCode,
      });
    }
    return true;
  };

  for (let index = 0; index < warmup; index++) {
    for (const sideName of order) {
      if (!(await runSide(sideName, 'warmup', index))) {
        return { baseline: sides.baseline, candidate: sides.candidate, fatal: true };
      }
    }
  }
  for (let index = 0; index < runs; index++) {
    for (const sideName of order) {
      if (!(await runSide(sideName, 'measure', index))) {
        return { baseline: sides.baseline, candidate: sides.candidate, fatal: true };
      }
    }
  }
  return { baseline: sides.baseline, candidate: sides.candidate, fatal: false };
}

// 一侧的 collect 口径报告：command/runs/warmup/timeout_ms/unit/samples/summary/errors。
function buildSideReport(command, runs, warmup, timeoutMs, side) {
  return {
    command,
    runs,
    warmup,
    timeout_ms: timeoutMs,
    unit: 'ns',
    samples: side.samples,
    summary: side.samples.length === 0
      ? emptySummary()
      : computeSummary(side.samples.map((s) => s.duration_ns)),
    errors: side.errors,
  };
}

async function ab(tokens) {
  const { values, error: parseError } = parseArgs(tokens, KNOWN_KEYS);
  if (parseError) {
    return fail(parseError);
  }

  const baselineCommand = values['baseline-command'];
  const candidateCommand = values['candidate-command'];
  const output = values.output;
  if (baselineCommand === undefined || baselineCommand === '') {
    return fail('--baseline-command 不能为空');
  }
  if (candidateCommand === undefined || candidateCommand === '') {
    return fail('--candidate-command 不能为空');
  }
  if (output === undefined || output === '') {
    return fail('--output 不能为空');
  }

  const runsR = parsePositiveIntOption(values, 'runs', { min: 2, required: true });
  if (runsR.error) {
    return fail(runsR.error);
  }
  const warmupR = parsePositiveIntOption(values, 'warmup', { min: 0, required: false });
  if (warmupR.error) {
    return fail(warmupR.error);
  }
  const timeoutR = parsePositiveIntOption(values, 'timeout-ms', { min: 1, required: true });
  if (timeoutR.error) {
    return fail(timeoutR.error);
  }
  const alphaR = parseNumberOption(values, 'alpha', {
    defaultValue: DEFAULT_ALPHA,
    check: (v) => v > 0 && v < 1,
    describe: '满足 0 < alpha < 1',
  });
  if (alphaR.error) {
    return fail(alphaR.error);
  }
  const minChangeR = parseNumberOption(values, 'min-change-percent', {
    defaultValue: DEFAULT_MIN_CHANGE_PERCENT,
    check: (v) => v >= 0,
    describe: '为不小于 0 的数',
  });
  if (minChangeR.error) {
    return fail(minChangeR.error);
  }

  const runs = runsR.value;
  const warmup = warmupR.value === undefined ? 0 : warmupR.value;
  const timeoutMs = timeoutR.value;
  const alpha = alphaR.value;
  const minChangePercent = minChangeR.value;

  const { baseline, candidate, fatal } = await executeInterleaved(
    baselineCommand, candidateCommand, runs, warmup, timeoutMs);
  // 进程无法启动属致命错误：stderr 已报告，不创建或改写 output。
  if (fatal) {
    return EXIT_USAGE;
  }

  const baselineReport = buildSideReport(baselineCommand, runs, warmup, timeoutMs, baseline);
  const candidateReport = buildSideReport(candidateCommand, runs, warmup, timeoutMs, candidate);

  // 两侧都至少有两个 exit_code 为 0 的样本时，按 compare 口径给出比较结果。
  const baselineDurations = baselineReport.samples.map((s) => s.duration_ns);
  const candidateDurations = candidateReport.samples.map((s) => s.duration_ns);
  let comparison = null;
  if (baselineDurations.length >= 2 && candidateDurations.length >= 2) {
    const {
      baselineSummary, candidateSummary, delta, welch, attribution,
    } = buildCompareResult(
      { command: baselineCommand, durations: baselineDurations },
      { command: candidateCommand, durations: candidateDurations },
    );
    comparison = {
      baseline_summary: baselineSummary,
      candidate_summary: candidateSummary,
      delta,
      welch,
      decision: decide(welch.p_value, alpha, delta.mean.percent, minChangePercent),
      attribution,
    };
  }

  const report = {
    baseline: baselineReport,
    candidate: candidateReport,
    comparison,
  };

  let payload;
  try {
    payload = JSON.stringify(report, null, 2) + '\n';
  } catch (err) {
    process.stderr.write(`perf-regress: 结果序列化失败: ${err.message}\n`);
    return EXIT_OUTPUT_ERROR;
  }

  try {
    await fs.writeFile(output, payload, 'utf8');
  } catch (err) {
    process.stderr.write(`perf-regress: 无法写入 --output ${output}: ${err.message}\n`);
    return EXIT_OUTPUT_ERROR;
  }

  const hasMeasureErrors = baselineReport.errors.some((e) => e.stage === 'measure')
    || candidateReport.errors.some((e) => e.stage === 'measure');
  const insufficientSamples = baselineDurations.length < 2 || candidateDurations.length < 2;
  return hasMeasureErrors || insufficientSamples ? EXIT_MEASURE_ERROR : EXIT_OK;
}

module.exports = {
  ab,
  executeInterleaved,
};

'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');
const { round6 } = require('./stats');
const { parseArgs, EXIT_OK, EXIT_USAGE, EXIT_OUTPUT_ERROR } = require('./collect');
const {
  loadInput,
  buildCompareResult,
  decide,
  parseNumberOption,
  DEFAULT_ALPHA,
  DEFAULT_MIN_CHANGE_PERCENT,
} = require('./compare');

const KNOWN_KEYS = new Set(['manifest', 'output', 'alpha', 'min-change-percent']);

function fail(message) {
  process.stderr.write(`perf-regress: ${message}\n`);
  return EXIT_USAGE;
}

// Benjamini–Hochberg 校正：m 个 p 值升序后记 p_(1)<=...<=p_(m)，
// q_(i) = min(1, min over j>=i (m*p_(j)/j))，再映回原序，保留六位小数。
function benjaminiHochberg(pValues) {
  const m = pValues.length;
  const order = Array.from({ length: m }, (_, i) => i)
    .sort((a, b) => pValues[a] - pValues[b]);
  const adjusted = new Array(m);
  let running = 1;
  // 从最大秩向最小秩扫描，累积 min
  for (let rank = m; rank >= 1; rank--) {
    const index = order[rank - 1];
    running = Math.min(running, (m * pValues[index]) / rank);
    adjusted[index] = round6(Math.min(1, running));
  }
  return adjusted;
}

// 多项归因百分比的中位数：null 按正无穷参与比较；结果为正无穷时写回 null。
function medianPercent(values) {
  const sorted = values
    .map((v) => (v === null ? Infinity : v))
    .sort((a, b) => a - b);
  const n = sorted.length;
  const mid = n >> 1;
  const median = n % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
  return median === Infinity ? null : round6(median);
}

// suite 归因的 dominant_factor，口径与 compare 相同：
// central_tendency > tail_latency > variability，取最大正值，无正值为 none。
function dominantFactor(central, tail, variability) {
  const entries = [
    ['central_tendency', central],
    ['tail_latency', tail],
    ['variability', variability],
  ];
  let dominant = null;
  let best = 0;
  for (const [name, percent] of entries) {
    const effective = percent === null ? Infinity : percent;
    if (effective > 0 && effective > best) {
      best = effective;
      dominant = name;
    }
  }
  return dominant === null ? 'none' : dominant;
}

// 读取并校验 manifest：UTF-8 JSON 对象，cases 为非空数组；
// 每项 name 非空且唯一，baseline/candidate 非空。
// 相对路径按 manifest 所在目录解析。返回 { manifestDir, cases } 或 { error }。
async function loadManifest(manifestPath) {
  let text;
  try {
    text = await fs.readFile(manifestPath, 'utf8');
  } catch (err) {
    return { error: `无法读取 manifest 文件 ${manifestPath}: ${err.message}` };
  }
  let manifest;
  try {
    manifest = JSON.parse(text);
  } catch {
    return { error: `manifest 文件不是合法 JSON: ${manifestPath}` };
  }
  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
    return { error: 'manifest 结构无效: 顶层须为对象' };
  }
  if (!Array.isArray(manifest.cases) || manifest.cases.length === 0) {
    return { error: 'manifest cases 必须为非空数组' };
  }

  const manifestDir = path.dirname(path.resolve(manifestPath));
  const cases = [];
  const names = new Set();
  for (let i = 0; i < manifest.cases.length; i++) {
    const item = manifest.cases[i];
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      return { error: `manifest cases[${i}] 必须为对象` };
    }
    if (typeof item.name !== 'string' || item.name === '') {
      return { error: `manifest cases[${i}] 的 name 必须为非空字符串` };
    }
    if (names.has(item.name)) {
      return { error: `manifest cases 中 name 重复: ${item.name}` };
    }
    if (typeof item.baseline !== 'string' || item.baseline === '') {
      return { error: `manifest cases[${i}] (${item.name}) 的 baseline 必须为非空字符串` };
    }
    if (typeof item.candidate !== 'string' || item.candidate === '') {
      return { error: `manifest cases[${i}] (${item.name}) 的 candidate 必须为非空字符串` };
    }
    names.add(item.name);
    cases.push({
      name: item.name,
      baselinePath: path.resolve(manifestDir, item.baseline),
      candidatePath: path.resolve(manifestDir, item.candidate),
    });
  }
  return { manifestDir, cases };
}

async function compareSuite(tokens) {
  const { values, error: parseError } = parseArgs(tokens, KNOWN_KEYS);
  if (parseError) {
    return fail(parseError);
  }

  const manifestPath = values.manifest;
  const output = values.output;
  if (manifestPath === undefined || manifestPath === '') {
    return fail('--manifest 不能为空');
  }
  if (output === undefined || output === '') {
    return fail('--output 不能为空');
  }

  const alphaR = parseNumberOption(values, 'alpha', {
    defaultValue: DEFAULT_ALPHA,
    check: (v) => v > 0 && v < 1,
    describe: '满足 0 < alpha < 1',
  });
  if (alphaR.error) {
    return fail(alphaR.error);
  }
  const minChangeR = parseNumberOption(values, 'min-change-percent', {
    defaultValue: DEFAULT_MIN_CHANGE_PERCENT,
    check: (v) => v >= 0,
    describe: '为不小于 0 的数',
  });
  if (minChangeR.error) {
    return fail(minChangeR.error);
  }
  const alpha = alphaR.value;
  const minChangePercent = minChangeR.value;

  // 全部校验通过后才写 output：manifest 校验与每对输入的加载/校验先行。
  const manifestR = await loadManifest(manifestPath);
  if (manifestR.error) {
    return fail(manifestR.error);
  }

  const loaded = [];
  for (const c of manifestR.cases) {
    const baseline = await loadInput(c.baselinePath, `case "${c.name}" 的 baseline`);
    if (baseline.error) {
      return fail(baseline.error);
    }
    const candidate = await loadInput(c.candidatePath, `case "${c.name}" 的 candidate`);
    if (candidate.error) {
      return fail(candidate.error);
    }
    if (baseline.command !== candidate.command) {
      return fail(`case "${c.name}" 两份输入的 command 不一致`);
    }
    loaded.push({ name: c.name, command: baseline.command, baseline, candidate });
  }

  // 按 compare 口径重算每个 case，并汇总原始 p 值做 BH 校正。
  const computed = loaded.map((entry) => {
    const result = buildCompareResult(entry.baseline, entry.candidate);
    return { name: entry.name, command: entry.command, ...result };
  });
  const adjusted = benjaminiHochberg(computed.map((c) => c.welch.p_value));

  const counts = {
    regression: 0,
    improvement: 0,
    no_material_change: 0,
    not_significant: 0,
  };
  const caseResults = computed.map((c, i) => {
    const adjustedPValue = adjusted[i];
    const decision = decide(adjustedPValue, alpha, c.delta.mean.percent, minChangePercent);
    counts[decision] += 1;
    return {
      name: c.name,
      command: c.command,
      baseline_summary: c.baselineSummary,
      candidate_summary: c.candidateSummary,
      delta: c.delta,
      welch: c.welch,
      adjusted_p_value: adjustedPValue,
      decision,
      attribution: c.attribution,
    };
  });

  // 优先级：regression > improvement > no_material_change > not_significant
  const suiteDecision = counts.regression > 0 ? 'regression'
    : counts.improvement > 0 ? 'improvement'
      : counts.no_material_change > 0 ? 'no_material_change'
        : 'not_significant';

  const suiteSummary = {
