      adjustedPValue, alpha, c.delta.mean.percent, minChangePercent);
  } else {
    // 普通测量错误或任一侧有效样本少于 2：该 case 不具可比性。
    incomplete += 1;
  }

  return {
    name: spec.name,
    baseline: baselineReport,
    candidate: candidateReport,
    comparison,
    adjusted_p_value: adjustedPValue,
    decision: caseDecision,
  };
});

